content.content:
    MethodologySearchPage:
      type: object
      required: [items, nextCursor, methodologyVersion]
      additionalProperties: false
      properties:
        items: { type: array, items: { $ref: "#/components/schemas/MethodologySearchHit" } }
        nextCursor: { type: [string, "null"] }
        methodologyVersion: { $ref: "#/components/schemas/MethodologyVersionRef" }
    MethodologySearchHit:
      type: object
      description: "Plain text only (never HTML)."
      required: [blockRef, phaseCode, sectionBlockRef, lang, snippet, highlights]
      additionalProperties: false
      properties:
        blockRef: { type: string, pattern: '^B0[0-9]{3}$' }
        phaseCode: { type: [string, "null"], enum: [diagnose, define, design, mobilize, transform, realize, null] }
        sectionBlockRef: { type: [string, "null"] }
        lang: { type: string, enum: [en, ar] }
        snippet: { type: string }
        highlights: { type: array, maxItems: 50, items: { $ref: "#/components/schemas/SearchHighlight" } }
    MethodologyProvenance:
      type: object
      description: "A practical synthesis inspired by PMI/Brightline/BRM with custom extensions; never an official PMI standard or certified product (M0089)."
      required: [statement, connectionNote, foundations, customExtensions, realizeNote, note, methodologyVersion]
      additionalProperties: false
      properties:
        statement: { $ref: "#/components/schemas/SourceBlockText" }
        connectionNote: { $ref: "#/components/schemas/SourceBlockText" }
        foundations: { type: array, maxItems: 3, items: { $ref: "#/components/schemas/SourceFoundation" } }
        customExtensions: { type: array, maxItems: 6, items: { $ref: "#/components/schemas/SourceBlockText" } }
        realizeNote: { $ref: "#/components/schemas/SourceBlockText" }
        note: { oneOf: [{ $ref: "#/components/schemas/ProvenanceNote" }, { type: "null" }] }
        methodologyVersion: { $ref: "#/components/schemas/MethodologyVersionRef" }
    MethodologyElementProfileList:
      type: object
      required: [methodologyVersion, items]
      additionalProperties: false
      properties:
        methodologyVersion: { $ref: "#/components/schemas/MethodologyVersionRef" }
        items: { type: array, maxItems: 100, items: { $ref: "#/components/schemas/MethodologyElementProfile" } }
    MethodologyElementProfile:
      type: object
      description: "provenance follows B0156-B0162; overridden is true when the resolved version overrides the seeded default through Studio."
      required: [elementRef, kind, stableKey, ordinal, labelEn, labelAr, provenance, provenanceSourceRef, questionTag, sourceRefs, overridden]
      additionalProperties: false
      properties:
        elementRef: { type: string }
        kind: { type: string, enum: [phase, gate, tom_dimension, template, scoring_model, forum, launch_window, health_check, roaming_example, traceability_chain, benefit_lifecycle_step] }
        stableKey: { type: string }
        ordinal: { type: integer }
        labelEn: { type: string }
        labelAr: { type: string }
        provenance: { type: string, enum: [custom_extension, foundation_inspired] }
        provenanceSourceRef: { type: string, enum: [B0156, B0158, B0159, B0160, B0161, B0162] }
        questionTag: { type: [string, "null"], enum: [why_change, what_different, how_execute, how_prove_value, null] }
        sourceRefs: { type: array, maxItems: 10, items: { type: string, pattern: '^B0[0-9]{3}$' } }
        overridden: { type: boolean }
    GuidingQuestionList:
      type: object
      description: "The four B0016 questions, English verbatim; Arabic provisional."
      required: [items]
      additionalProperties: false
      properties:
        items: { type: array, maxItems: 4, items: { $ref: "#/components/schemas/GuidingQuestion" } }
    GuidingQuestion:
      type: object
      required: [code, ordinal, textEn, textAr, sourceRef]
      additionalProperties: false
      properties:
        code: { type: string, enum: [why_change, what_different, how_execute, how_prove_value] }
        ordinal: { type: integer }
        textEn: { type: string }
        textAr: { type: string }
        sourceRef: { type: string }
NONE MethodologyProvenanceBlock
    SourceFoundation:
      type: object
      description: "A row of the B0156 table (Source / Used for), verbatim; Arabic provisional."
      required: [code, ordinal, sourceEn, sourceAr, usedForEn, usedForAr, sourceRef]
      additionalProperties: false
      properties:
        code: { type: string }
        ordinal: { type: integer }
        sourceEn: { type: string }
        sourceAr: { type: string }
        usedForEn: { type: string }
        usedForAr: { type: string }
        sourceRef: { type: string }

tool_use_result.stdout:
    MethodologySearchPage:
      type: object
      required: [items, nextCursor, methodologyVersion]
      additionalProperties: false
      properties:
        items: { type: array, items: { $ref: "#/components/schemas/MethodologySearchHit" } }
        nextCursor: { type: [string, "null"] }
        methodologyVersion: { $ref: "#/components/schemas/MethodologyVersionRef" }
    MethodologySearchHit:
      type: object
      description: "Plain text only (never HTML)."
      required: [blockRef, phaseCode, sectionBlockRef, lang, snippet, highlights]
